-- PT106-S1-Q8. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT106-S1-Q8$batch03$ AND q.stimulus=$batch03$Generally speaking, if the same crop is sown in a field for several successive years, growth in the later years is poorer than growth in the earlier years, since nitrogen in the soil becomes depleted. Even though alfalfa is a nitrogen-fixing plant and thus increases the amount of nitrogen in the soil, surprisingly, it too, if planted in the same field year after year, grows less well in the later years than it does in the earlier years.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to explain the similarity described above between alfalfa and non-nitrogen-fixing plants?$batch03$ AND q.correct_choice=$batch03$C$batch03$) THEN RAISE EXCEPTION 'Question changed: PT106-S1-Q8'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT106-S1-Q8$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT106-S1-Q8'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT106-S1-Q8$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Most crops grow worse in later years because they use up the soil's nitrogen. Alfalfa adds nitrogen to the soil.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Alfalfa still grows worse year after year when planted in the same field?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Nitrogen cannot be alfalfa's problem, since it makes its own. So something *else* about growing in the same spot must be hurting it. What builds up or runs down when the same plant grows in one field for years? Pests, disease, or something the plant itself leaves behind.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a cause of decline other than nitrogen loss that applies to alfalfa.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT106-S1-Q8$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$"Some kinds of plants" do better among other species. We are not told alfalfa is one of them, and this does not give a mechanism for its year-to-year decline.$batch03$), ($batch03$B$batch03$, $batch03$This explains how alfalfa adds usable nitrogen. It confirms the expectation that alfalfa should not run short, so it makes the decline more puzzling.$batch03$), ($batch03$C$batch03$, $batch03$Alfalfa produces substances that build up in the soil and poison it. Each year in the same field, more of the toxin is there. That is a reason for decline that has nothing to do with nitrogen.$batch03$), ($batch03$D$batch03$, $batch03$Alfalfa adds nitrogen only when certain bacteria are present. The stimulus already says alfalfa increases nitrogen, and we are not told the bacteria are missing, so this does not explain the decline.$batch03$), ($batch03$E$batch03$, $batch03$No black walnut trees are mentioned. A sensitivity to their leaves cannot explain decline in an ordinary alfalfa field.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT106-S1-Q8$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
